const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Geometry for the northern part of Lake Eyre, South Australia.
  const aoi = ee.Geometry.Polygon([[
    [137.02, -27.8], [137.8, -27.8],
    [137.8, -28.7], [137.02, -28.7],
    [137.02, -27.8]
  ]]);

  // Define the time periods.
  const startDate1 = '2025-06-15';
  const endDate1 = '2025-06-30';
  const startDate2 = '2025-09-10';
  const endDate2 = '2025-09-20';

  // 2. Data Acquisition & Processing Function
  function getWaterExtent(startDate, endDate, geometry) {
    // Using Sentinel-2 MSI
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterDate(startDate, endDate)
      .filterBounds(geometry)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    // Check if the collection is empty.
    const collectionSize = collection.size().getInfo();
    if (collectionSize === 0) {
      return {
        'count': 0,
        'water_pixels': null,
        'image_count': 0
      };
    }

    // Create a cloud-masked median composite.
    const image = collection.map(maskS2clouds).median();

    // Calculate MNDWI to identify water. Green = B3, SWIR1 = B11.
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');

    // Threshold MNDWI to create a water mask. A threshold > 0 is standard for MNDWI.
    const waterMask = mndwi.gt(0);
    const waterArea = waterMask.updateMask(waterMask); // Mask non-water pixels

    // Calculate the number of water pixels.
    const stats = waterArea.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 1000,
      maxPixels: 1e9
    });

    return {
      'count': stats.get('MNDWI').getInfo(),
      'water_pixels': stats.get('MNDWI'),
      'image_count': collectionSize
    };
  }

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    let mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000);
  }

  // 3. Calculation & Validation
  const period1 = getWaterExtent(startDate1, endDate1, aoi);
  console.log(`Period 1 (June 2025) Images: ${period1.image_count}`);

  // Exit if no images found in the first period.
  if (period1.image_count === 0) {
    console.log(`Evidence: No satellite imagery found for the specified future date range (${startDate1} to ${endDate1}).`);
    console.log('A: No');
    return;
  }

  // The code below is for completeness but will not be reached due to future dates.
  const period2 = getWaterExtent(startDate2, endDate2, aoi);
  console.log(`Period 2 (September 2025) Images: ${period2.image_count}`);

  if (period2.image_count === 0) {
    console.log(`Evidence: No satellite imagery found for the second future date range (${startDate2} to ${endDate2}).`);
    console.log('C1: Empty Collection');
    return;
  }

  const waterPixels1 = period1.count;
  const waterPixels2 = period2.count;

  if (waterPixels1 === null || waterPixels2 === null) {
    console.log('Evidence: Calculation failed, likely due to no valid pixels after cloud masking.');
    console.log('C2: No Valid Pixels');
    return;
  }

  console.log(`Period 1 Water Pixels: ${waterPixels1}`);
  console.log(`Period 2 Water Pixels: ${waterPixels2}`);

  if (waterPixels2 > waterPixels1) {
    console.log('A: Yes');
  } else {
    console.log('B: No');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
  }
}

initEE();
